/* Render every slide of the deck at 1920x1080 into pitch-deck/png/. */
import { chromium } from 'playwright';

const DECK = 'file:///Users/ag/Documents/04_projects/ehl-muc-aug/challenge/pitch-deck/index.html';
const OUT = process.argv[2];

const browser = await chromium.launch({
    channel: 'chrome',
    args: ['--use-gl=angle', '--use-angle=metal', '--enable-unsafe-swiftshader', '--allow-file-access-from-files'],
});
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 });
page.on('console', m => { if (m.type() === 'error') console.log('  [console]', m.text()); });
page.on('pageerror', e => console.log('  [pageerror]', e.message));

await page.goto(DECK, { waitUntil: 'networkidle', timeout: 60000 });
await page.waitForTimeout(2500);

const n = await page.locator('section.slide').count();
console.log('slides:', n);

for (let i = 0; i < n; i++) {
    if (i > 0) { await page.keyboard.press('ArrowRight'); }
    await page.waitForTimeout(1800);
    const name = `slide-${String(i + 1).padStart(2, '0')}.png`;
    await page.screenshot({ path: `${OUT}/${name}` });

    // overflow check: does anything inside this slide spill past the 1080 frame?
    const spill = await page.evaluate(() => {
        const s = document.querySelector('section.slide.active');
        if (!s) return 'no active slide';
        const pad = s.querySelector('.pad');
        const over = [];
        if (pad && pad.scrollHeight > pad.clientHeight + 1) {
            over.push(`pad overflows by ${pad.scrollHeight - pad.clientHeight}px`);
        }
        const r = s.getBoundingClientRect();
        s.querySelectorAll('*').forEach(el => {
            const b = el.getBoundingClientRect();
            if (b.height && (b.bottom > r.bottom + 1 || b.right > r.right + 1)) {
                over.push(`${el.className || el.tagName} bottom=${Math.round(b.bottom)} right=${Math.round(b.right)}`);
            }
        });
        return over.slice(0, 4);
    });
    console.log(name, Array.isArray(spill) && spill.length === 0 ? 'ok' : spill);
}

await browser.close();

